# Check chromatic number - find the actual chromatic number
# Since we have a 5-coloring, it's at most 5. Let's check if it's 2, 3, or 4.
# Let's try to find a proper coloring with fewer colors using brute force for small k

def is_colorable(k):
    """Check if graph is k-colorable using backtracking"""
    colors = [-1] * n
    adj = {i: set() for i in range(n)}
    for u,v in edges:
        adj[u].add(v)
        adj[v].add(u)

    def backtrack(v):
        if v == n:
            return True
        used = set()
        for u in adj[v]:
            if colors[u] != -1:
                used.add(colors[u])
        for c in range(k):
            if c not in used:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

for k in range(1, 6):
    if is_colorable(k):
        print(f"Chromatic number: {k}")
        break

# Let's also verify the 5-coloring from the SAT solver
colors = {0: 1, 1: 2, 2: 1, 3: 1, 4: 0, 5: 0, 6: 0, 7: 0, 8: 0, 9: 0, 10: 0, 11: 0, 12: 0}
proper = True
for u,v in edges:
    if colors[u] == colors[v]:
        proper = False
        print(f"Improper: {u} and {v} both color {colors[u]}")
if proper:
    print("SAT solver coloring is proper")
